const cfg = $json || {};

if (!cfg.locationId) throw new Error('Missing locationId');
if (!cfg.apiKey) throw new Error('Missing apiKey');

cfg.apiBaseUrl = cfg.apiBaseUrl || 'https://services.leadconnectorhq.com';
cfg.dryRun = cfg.dryRun !== undefined ? !!cfg.dryRun : true;

const baseUrl = cfg.apiBaseUrl.replace(/\/$/, '');
const headers = {
  Authorization: `Bearer ${cfg.apiKey}`,
  Version: '2021-07-28',
  'Content-Type': 'application/json',
  Accept: 'application/json',
};

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') {
    return await $httpRequest(options);
  }
  if (typeof this !== 'undefined' && this?.helpers?.httpRequest) {
    return await this.helpers.httpRequest(options);
  }
  throw new Error('HTTP not available in Code node runtime');
}

async function apiRequest(method, path, bodyPayload) {
  const options = {
    method,
    url: `${baseUrl}${path}`,
    headers,
    json: true,
  };
  if (bodyPayload !== undefined) options.body = bodyPayload;

  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, status: 200, data };
  } catch (err) {
    return {
      ok: false,
      status: err?.statusCode || err?.httpCode || err?.cause?.statusCode || 500,
      data: err?.response?.body || err?.message || err,
    };
  }
}

function getArrayPayload(obj, preferredKeys = []) {
  if (Array.isArray(obj)) return obj;
  for (const key of preferredKeys) {
    if (Array.isArray(obj?.[key])) return obj[key];
  }
  if (Array.isArray(obj?.data)) return obj.data;
  if (Array.isArray(obj?.customFields)) return obj.customFields;
  if (Array.isArray(obj?.data?.customFields)) return obj.data.customFields;
  return [];
}

function extractFieldName(field) {
  return field?.name || field?.label || field?.fieldName || '';
}

function normalizeType(value) {
  const v = String(value || '').toUpperCase();
  if (!v) return '';
  if (v.includes('NUMBER') || v === 'NUMERIC' || v === 'NUMERICAL') return 'NUMBER';
  if (['DATE_TIME', 'DATETIME'].includes(v)) return 'DATETIME';
  if (v === 'DATE') return 'DATE';
  return 'TEXT';
}

function extractFieldType(field) {
  return normalizeType(field?.dataType || field?.fieldType || field?.type || field?.valueType);
}

const targetGroupName = 'Apollo Enrichment';

const requiredFields = [
  { name: 'Apollo Contact Id', requiredType: 'TEXT' },
  { name: 'Apollo Account Id', requiredType: 'TEXT' },
  { name: 'Apollo Email Status', requiredType: 'TEXT' },
  { name: 'Apollo Primary Email Source', requiredType: 'TEXT' },
  { name: 'Apollo Primary Email Verification Source', requiredType: 'TEXT' },
  { name: 'Apollo Email Confidence', requiredType: 'NUMBER' },
  { name: 'Apollo Primary Email Catch-all Status', requiredType: 'TEXT' },
  { name: 'Apollo Primary Email Last Verified At', requiredType: 'DATE' },
  { name: 'Apollo Seniority', requiredType: 'TEXT' },
  { name: 'Apollo Departments', requiredType: 'TEXT' },
  { name: 'Apollo Sub Departments', requiredType: 'TEXT' },
  { name: 'Apollo Company Employees', requiredType: 'NUMBER' },
  { name: 'Apollo Industry', requiredType: 'TEXT' },
  { name: 'Apollo Keywords', requiredType: 'TEXT' },
  { name: 'Apollo Person LinkedIn URL', requiredType: 'TEXT' },
  { name: 'Apollo Company LinkedIn URL', requiredType: 'TEXT' },
  { name: 'Apollo Facebook URL', requiredType: 'TEXT' },
  { name: 'Apollo Twitter URL', requiredType: 'TEXT' },
  { name: 'Apollo Technologies', requiredType: 'TEXT' },
  { name: 'Apollo Annual Revenue', requiredType: 'NUMBER' },
  { name: 'Apollo Total Funding', requiredType: 'NUMBER' },
  { name: 'Apollo Latest Funding', requiredType: 'TEXT' },
  { name: 'Apollo Latest Funding Amount', requiredType: 'NUMBER' },
  { name: 'Apollo Last Raised At', requiredType: 'DATE' },
  { name: 'Apollo Subsidiary Of', requiredType: 'TEXT' },
  { name: 'Apollo Secondary Email', requiredType: 'TEXT' },
  { name: 'Apollo Secondary Email Source', requiredType: 'TEXT' },
  { name: 'Apollo Secondary Email Status', requiredType: 'TEXT' },
  { name: 'Apollo Secondary Email Verification Source', requiredType: 'TEXT' },
  { name: 'Apollo Tertiary Email', requiredType: 'TEXT' },
  { name: 'Apollo Tertiary Email Source', requiredType: 'TEXT' },
  { name: 'Apollo Tertiary Email Status', requiredType: 'TEXT' },
  { name: 'Apollo Tertiary Email Verification Source', requiredType: 'TEXT' },
  { name: 'Apollo Primary Intent Topic', requiredType: 'TEXT' },
  { name: 'Apollo Primary Intent Score', requiredType: 'NUMBER' },
  { name: 'Apollo Secondary Intent Topic', requiredType: 'TEXT' },
  { name: 'Apollo Secondary Intent Score', requiredType: 'NUMBER' },
  { name: 'Apollo Qualify Contact', requiredType: 'TEXT' },
];

const fieldsRes = await apiRequest.call(this, 'GET', `/locations/${cfg.locationId}/customFields?model=contact`);
if (!fieldsRes.ok) {
  throw new Error(`Failed to fetch custom fields: ${fieldsRes.status} ${JSON.stringify(fieldsRes.data)}`);
}

const existingFields = getArrayPayload(fieldsRes.data, ['customFields']);
const fieldByName = new Map();
for (const field of existingFields) {
  const name = extractFieldName(field);
  if (name) fieldByName.set(name, field);
}

const conflicts = [];
const report = [];
const toCreate = [];

for (const req of requiredFields) {
  const existing = fieldByName.get(req.name);
  if (existing) {
    const existingType = extractFieldType(existing);
    if (existingType !== req.requiredType) {
      conflicts.push({
        fieldName: req.name,
        existingType: existing?.dataType || existing?.fieldType || existing?.type || 'UNKNOWN',
        requiredType: req.requiredType,
      });
    } else {
      report.push({
        fieldName: req.name,
        fieldId: existing.id || existing._id || 'N/A',
        type: req.requiredType,
        action: 'Reused',
        group: targetGroupName,
      });
    }
  } else {
    toCreate.push(req);
  }
}

if (conflicts.length) {
  return [{
    json: {
      dryRun: cfg.dryRun,
      locationId: cfg.locationId,
      targetGroupName,
      CONFLICT: conflicts,
    },
  }];
}

async function createField(req) {
  const dataTypes = req.requiredType === 'NUMBER'
    ? ['NUMERIC', 'NUMBER']
    : req.requiredType === 'DATE'
      ? ['DATE']
      : req.requiredType === 'DATETIME'
        ? ['DATE_TIME', 'DATETIME']
        : ['TEXT', 'LARGE_TEXT'];

  let lastError = null;
  for (const dataType of dataTypes) {
    const bodies = [
      { name: req.name, model: 'contact', dataType },
      { name: req.name, objectKey: 'contact', dataType },
      { name: req.name, model: 'contact', dataType, group: targetGroupName },
      { name: req.name, model: 'contact', dataType, folder: targetGroupName },
      { name: req.name, model: 'contact', dataType, category: targetGroupName },
    ];

    for (const bodyPayload of bodies) {
      const res = await apiRequest.call(this, 'POST', `/locations/${cfg.locationId}/customFields`, bodyPayload);
      if (res.ok) return res.data;
      lastError = { status: res.status, data: res.data, body: bodyPayload };
    }
  }

  throw new Error(`Failed creating field ${req.name}: ${JSON.stringify(lastError)}`);
}

if (!cfg.dryRun) {
  for (const req of toCreate) {
    const created = await createField.call(this, req);
    report.push({
      fieldName: req.name,
      fieldId: created?.id || created?.data?.id || created?.customField?.id || 'N/A',
      type: req.requiredType,
      action: 'Created',
      group: targetGroupName,
    });
  }
} else {
  for (const req of toCreate) {
    report.push({
      fieldName: req.name,
      fieldId: 'N/A',
      type: req.requiredType,
      action: 'Planned Create (dryRun)',
      group: targetGroupName,
    });
  }
}

report.sort((a, b) => a.fieldName.localeCompare(b.fieldName));

return [{
  json: {
    dryRun: cfg.dryRun,
    locationId: cfg.locationId,
    targetGroupName,
    CUSTOM_FIELDS: report,
  },
}];
